from bisect import bisect_left

def binary_search(arr, target):
    pos = bisect_left(arr, target)

    if pos < len(arr) and arr[pos] == target:
        return pos

    return -1

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)
